SELECT ROUND(AVG(credit_score), 0)
FROM user_credit
WHERE deleted = 0
AND create_time >= #{start}
AND create_time <= #{end}

SELECT COUNT(*)
FROM user_credit
WHERE deleted = 0
AND credit_level IN ('较差', '极差')
AND create_time >= #{start}
AND create_time <= #{end}

SELECT id
FROM user_info
WHERE deleted = 0 AND nickname = #{nickname}
